    var owner, repo, headSha, inputFolder, jenkinsBasePath, diffText;

    if (_isScm(scmOrOwner)) {
        scm = scmOrOwner;
        headSha = repoOrHeadSha;
        inputFolder = headShaOrInputFolder;
