        }
        if (!currentRule) return;
        var detail = line.match(/^\s*(.+?):(\d+):\s*(.+?)\s*$/);
        if (!detail) return;
        taken[idx] = true;
        out.push({
            check: checkName,
            rule: currentRule,
            path: detail[1],
            line: parseInt(detail[2], 10),
            detail: detail[3]
        });
    });
}

