        assert.equal(items.length, 2, 'one item per [FAIL] section');
        assert.equal(items[0].path, 'a/one.dart');
        assert.equal(items[0].rule, 'method_size');
        assert.equal(items[1].path, 'b/two.dart');
        assert.equal(items[1].rule, 'file_size');
    });
});

